const body = $input.first().json.body || {};

const images = body.images || [];
const audioPath = body.audio_path;
const outputName = body.output_name || `video_${Date.now()}.mp4`;
const fps = body.fps || 24;
const outputPath = `/files/${outputName}`;
const workDir = body.work_dir || '/tmp';

if (images.length === 0) throw new Error('缺少图片列表 (images)');
if (!audioPath) throw new Error('缺少音频路径 (audio_path)');

// 构建 ffmpeg concat 文件内容
let concatContent = '';
images.forEach(img => {
  concatContent += `file '${img.path}'\n`;
  concatContent += `duration ${img.duration || 5}\n`;
});
// 最后一张图片需要再写一次 file 行 (ffmpeg concat 规范)
if (images.length > 0) {
  concatContent += `file '${images[images.length - 1].path}'\n`;
}

const concatFile = `${workDir}/concat_${Date.now()}.txt`;

// FFmpeg 命令
const cmd = [
  `echo '${concatContent.replace(/'/g, "'\\''")}' > ${concatFile}`,
  `&&`,
  `ffmpeg -y -f concat -safe 0 -i ${concatFile}`,
  `-i '${audioPath}'`,
  `-c:v libx264 -pix_fmt yuv420p -r ${fps}`,
  `-c:a aac -shortest`,
  `'${outputPath}'`,
  `&&`,
  `echo 'SUCCESS'`,
  `||`,
  `echo 'FAILED'`
].join(' ');

return [{
  json: {
    command: cmd,
    outputPath: outputPath,
    outputName: outputName,
    imageCount: images.length,
    hasAudio: !!audioPath
  }
}];

const { execSync } = require('child_process');

const command = $input.first().json.command;

try {
  const stdout = execSync(command, {
    timeout: 300000,
    shell: '/bin/bash',
    encoding: 'utf-8',
    maxBuffer: 50 * 1024 * 1024
  });
  return [{
    json: {
      stdout: stdout,
      stderr: '',
      exitCode: 0
    }
  }];
} catch (error) {
  return [{
    json: {
      stdout: error.stdout || '',
      stderr: error.stderr || error.message,
      exitCode: error.status || 1
    }
  }];
}

const output = $input.first().json.stdout || '';
const stderr = $input.first().json.stderr || '';

if (!output.includes('SUCCESS')) {
  return [{
    json: {
      success: false,
      error: 'FFmpeg 合成失败',
      output: output.substring(0, 500),
      stderr: stderr.substring(0, 500)
    }
  }];
}

return [{
  json: {
    success: true,
    message: '视频合成完成',
    stdout: output.substring(0, 200),
    generatedAt: new Date().toISOString()
  }
}];
